/// <summary>
/// PaffH 11.09.23
/// </summary>
/// <param name = "_custTable">CustTable</param>
/// <param name = "_nDXpAAddressContract">NDXpAAddressContract</param>
protected void populateContractFromCustTable(CustTable _custTable, NDXpAAddressContract _nDXpAAddressContract)
{
    next populateContractFromCustTable(_custTable, _nDXpAAddressContract);

    _nDXpAAddressContract.ParmAVATOSId(_custTable.KCS_TOSId);
}

/// <summary>
