/// <param name = "_logisticsLocation">LogisticsLocation</param>
/// <param name = "_nDXpAAddressContract">NDXpAAddressContract</param>
protected void populateLogisticsLocation(LogisticsLocation _logisticsLocation, NDXpAAddressContract _nDXpAAddressContract)
{
    next populateLogisticsLocation(_logisticsLocation, _nDXpAAddressContract);

    _nDXpAAddressContract.ParmAVAEDIGLN(_logisticsLocation.AVAEDIGLN);
}
